#!/usr/bin/env bash
#
# file-size-gate.sh — ratchet Go source file length down against a
# committed baseline.
#
#   scripts/file-size-gate.sh check     # CI gate (default)
#   scripts/file-size-gate.sh baseline  # regenerate .file-size-baseline.txt
#
# Limit: 500 lines. Non-test Go files under cmd/, internal/, pkg/ are
# measured, the same set complexity-gate.sh measures; tests, testdata/
# and generated files ("// Code generated ... DO NOT EDIT.") are not.
#
# The gate is a ratchet, not a quota:
#
#   1. A file over the limit that is NOT in the baseline fails the
#      gate — new and split files must meet the limit.
#   2. A baselined file that grew fails the gate — existing offenders
#      may not get longer.
#   3. A baselined file that shrank, dropped under the limit or was
#      removed is reported so the baseline can be shrunk; the gate
#      still passes. Run `baseline` to record the improvement.
#
# Baseline format, one entry per line, TAB-separated:
#   <lines>\t<file>
#
set -euo pipefail

cd "$(git rev-parse --show-toplevel)"

MODE="${1:-check}"
BASELINE=".file-size-baseline.txt"
MAX_LINES=500

tmp="$(mktemp -d)"
trap 'rm -rf "$tmp"' EXIT

# Generated files carry the marker before the package clause.
is_generated() {
    sed -n '1,/^package /p' "$1" | grep -qE '^// Code generated .* DO NOT EDIT\.$'
}

# Normalise to the baseline format, sorted by path for stable diffs.
measure() {
    find cmd internal pkg -name '*.go' -not -name '*_test.go' -not -path '*/testdata/*' 2>/dev/null \
        | sort \
        | while IFS= read -r f; do
            is_generated "$f" && continue
            n="$(wc -l < "$f" | tr -d ' ')"
            if [ "$n" -gt "$MAX_LINES" ]; then
                printf '%s\t%s\n' "$n" "$f"
            fi
        done
}

measure > "$tmp/current"

if [ "$MODE" = "baseline" ]; then
    {
        echo "# Generated by scripts/file-size-gate.sh baseline — do not edit by hand."
        echo "# lines<TAB>file"
        echo "# Non-test Go files over $MAX_LINES lines. Shrink worst-first."
        cat "$tmp/current"
    } > "$BASELINE"
    echo "file-size-gate: wrote $(grep -vc '^#' "$BASELINE") entries to $BASELINE"
    exit 0
fi

if [ ! -f "$BASELINE" ]; then
    echo "file-size-gate: no $BASELINE (run 'scripts/file-size-gate.sh baseline')" >&2
    exit 2
fi

grep -v '^#' "$BASELINE" > "$tmp/base" || true

fail=0

# 1. New offenders and 2. regressions.
while IFS=$'\t' read -r cur file; do
    base="$(awk -F'\t' -v f="$file" '$2 == f { print $1 }' "$tmp/base")"
    if [ -z "$base" ]; then
        echo "file-size-gate: NEW  $file has $cur lines — over $MAX_LINES and not baselined" >&2
        fail=1
    elif [ "$cur" -gt "$base" ]; then
        echo "file-size-gate: WORSE  $file $base -> $cur lines" >&2
        fail=1
    elif [ "$cur" -lt "$base" ]; then
        echo "file-size-gate: shrank  $file $base -> $cur lines — run 'make filesize-baseline'"
    fi
done < "$tmp/current"

# 3. Stale entries: now within the limit, or removed. Informational.
stale=0
while IFS=$'\t' read -r base file; do
    if ! awk -F'\t' -v f="$file" '$2 == f { found = 1 } END { exit !found }' "$tmp/current"; then
        echo "file-size-gate: stale baseline entry $file ($base lines) — run 'make filesize-baseline'"
        stale=$((stale + 1))
    fi
done < "$tmp/base"

echo "file-size-gate: $(wc -l < "$tmp/current" | tr -d ' ') files over $MAX_LINES lines (baseline $(wc -l < "$tmp/base" | tr -d ' '), stale $stale)"

if [ "$fail" -ne 0 ]; then
    echo "file-size-gate: FAIL — split the file by concern; the baseline only shrinks" >&2
    exit 1
fi
echo "file-size-gate: OK"
